test("plan pause scenario 3", { tag: '@functionality' }, async ({ browser }) => {
  const sheet = ui.sheetId();
  const pg_uma = await ui.userPage(browser, "uma", sheet);
  await ui.setToday(pg_uma, "2026-04-05");
  expect(await ui.setRole(pg_uma, "wes", "steward")).toBe(true);
  await ui.setSetting(pg_uma, "clerk-limit", "3.00");
  await ui.setSetting(pg_uma, "floor", "2.00");
  await ui.setSetting(pg_uma, "late-pct", "10.00");
  await ui.setSetting(pg_uma, "policy-date", "2026-03-15");
  await ui.setSetting(pg_uma, "period-numbering-from", "2026-03-01");
  await ui.setSetting(pg_uma, "cap", "5.00");
  await ui.setSetting(pg_uma, "perm-void", "clerk");
  await ui.setSetting(pg_uma, "entry-date", "2026-03-05");
  await ui.loadSheet(pg_uma, `${sheet}-p`);
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "20.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "12.50"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "12.50"})).toBe(true);
  const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "A"}));
  const c_ben_0 = ui.must(await ui.addClaim(pg_uma, p_ben, {"amount": "12.50"}));
  expect(await ui.claimAction(pg_uma, c_ben_0, "open")).toBe(true);
  await ui.loadSheet(pg_uma, sheet);
  await ui.setSetting(pg_uma, "parent", `${sheet}-p`);
  await ui.setSetting(pg_uma, "pot", "100.00");
  await ui.setSetting(pg_uma, "alert-threshold", "3.00");
  await ui.setSetting(pg_uma, "review-threshold", "4.00");
  await ui.setSetting(pg_uma, "proof-kinds", "receipt");
  await ui.setSetting(pg_uma, "default-grade", "B");
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "7.50"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "12.50"})).toBe(true);
  expect(await ui.addPeriod(pg_uma, {"name": "P1", "from": "2026-03-01", "to": "2026-03-15"})).toBe(true);
  expect(await ui.addPeriod(pg_uma, {"name": "P2", "from": "2026-03-16", "to": "2026-03-31"})).toBe(true);
  const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "A", "terms": "3"}));
  expect(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "C", "terms": "20", "tags": "b, a"})).toBeNull();
  const pl_cam_1 = ui.must(await ui.addPlan(pg_uma, p_cam, {"amount": "10.25", "start": "2026-03-01", "end": "2026-04-30", "every": "7"}));
  expect(await ui.statement(pg_uma, p_cam)).toBe(true);
  const c_cam_0 = ui.must(await ui.addClaimTwice(pg_uma, p_cam, {"amount": "0.04", "date": "2026-03-09"}));
  expect(await ui.claimCount(pg_uma, p_cam)).toBe(1);
  expect(await ui.setSettingDated(pg_uma, "proof-threshold", "", "2026-03-09", "")).toBe(true);
  expect(await ui.ratePreview(pg_uma, "B", "20.00")).toEqual({ count: 0, diff: "0.00" });
  expect(await ui.statement(pg_uma, p_cam)).toBe(true);
  expect(await ui.periodAction(pg_uma, "P1", "soft-close")).toBe(true);
  expect(await ui.addHoliday(pg_uma, "2026-03-18")).toBe(true);
  await ui.refresh(pg_uma);
  expect(await ui.editPerson(pg_uma, p_cam, {"grade": "C"})).toBe(true);
  expect(await ui.addNote(pg_uma, "")).toBe(false);
  expect(await ui.addComment(pg_uma, c_cam_0, "ok")).toBe(true);
  expect(await ui.addLine(pg_uma, c_cam_0, {"label": "x", "qty": "1", "unit": "0.01"})).toBe(true);
  const pg_wes = await ui.userPage(browser, "wes", sheet);
  expect(await ui.periodAction(pg_wes, "P1", "reopen")).toBe(true);
  expect(await ui.generatePlans(pg_wes)).toBe(6);

